#!/usr/bin/env bash
# 基準イラストの描き直し：頭身を下げたマスコット寄りの体型（全年齢向け、体の凹凸は描かない）
cd ~/Projects/canopus-dive
S="Cute anime-style kemono (furry) mascot character illustration for an all-ages kids-friendly game, clean lineart, soft cel shading, glossy highlights, full body, standing. Stylized mascot proportions about 3.5 heads tall with a big head, a soft round bean-shaped body and stubby limbs, smooth simplified torso with NO anatomical detail (no breasts, no navel, no curvy hips). Plain flat pure green (#00FF00) background, nothing else, no text."
gen(){ tools/gen_image.sh "$@" & }
gen art/raw/canopus_base.png "$S Character: CANOPUS, an energetic tomboyish orca x dragon girl. Keep the exact face, hair, ears, horns, colors and markings of the reference: glossy dark slate-black skin, cream-white muzzle and belly, yellow crescent markings on the thighs, yellow bands on the upper arms, big pointed ears with yellow rims, two small white horns, messy short silver-gray hair, amber eyes, a bright blue scarf, a thick orca tail with a white underside and tail flukes, chunky flipper-like forearms with small white claws. She also wears a small brown leather treasure-hunter satchel across the body. Big toothy confident grin, one fist raised." art/raw/canopus_v0.png
gen art/raw/mira_base.png "$S Character: MIRA, a shy small axolotl x dragon creature. Keep the exact head, colors and markings of the reference: glossy periwinkle-blue skin, cream-white belly with a small pink heart mark on the chest, round head with huge dark glossy eyes and pink dots on the forehead, axolotl gill fronds on the sides of the head, two long ear-fronds on top with pink stripes, pink bat-like wings with cream bones, a blue tail with a pink tip, pink feet. Smaller and rounder than a human, floating a little above the ground, waving one wing happily, blushing." art/raw/mira_v0.png
wait
